pub struct Breaker { st: AtomicU8, fails: AtomicU64, total: AtomicU64,
                     tripped: Mutex<Option<Instant>> }   // monotonic trip instant

pub fn admit(&self) -> Result<(), OpenCircuit> {
    if self.st.load(Ordering::Acquire) == OPEN {
        let cooling = self.tripped.lock().unwrap().is_some_and(|t| t.elapsed() < COOLDOWN);
        if cooling { return Err(OpenCircuit); }
        if self.st.compare_exchange(OPEN, HALF_OPEN, AcqRel, Acquire).is_err() {
            return Err(OpenCircuit);   // lost the half-open race: fail fast
        }
    }
    Ok(())
}
